<?php
class OlderAdultController{public function index():void{if(empty($_SESSION['user'])) redirect('/SICAM/public/');view('older_adults/index',['rows'=>OlderAdult::all()]);}public function create():void{view('older_adults/create');}public function store():void{if(!csrf_validate($_POST['csrf_token']??null)) exit('CSRF');OlderAdult::create(['tipo_documento'=>$_POST['tipo_documento'],'numero_documento'=>$_POST['numero_documento'],'nombres'=>$_POST['nombres'],'apellidos'=>$_POST['apellidos'],'fecha_nacimiento'=>$_POST['fecha_nacimiento'],'sexo'=>$_POST['sexo'],'eps'=>$_POST['eps'],'estado'=>$_POST['estado'],'fecha_ingreso'=>$_POST['fecha_ingreso']]);redirect('/SICAM/public/adultos-mayores');}}
